import ctypes, os
import numpy as np

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "liblap.so"))
_lib.lap.restype = ctypes.c_int
_lib.lap.argtypes = [ctypes.c_int, ctypes.c_void_p, ctypes.c_int, ctypes.c_int, ctypes.c_void_p]


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, np.ascontiguousarray(M, dtype=np.float64), check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if (M.ndim == 2 and M.shape == (n, n) and n > 0 and b.shape[0] == n
                and np.all(a == a[0]) and np.all(b == a[0])):
            rc = np.empty(n, dtype=np.int32)
            r = _lib.lap(n, M.ctypes.data, 12, 4, rc.ctypes.data)
            if r >= 0:
                G = np.zeros((n, n))
                G[np.arange(n), rc] = a
                return {"transport_plan": G}
        return {"transport_plan": _fallback(a, b, M)}

